"""Input validation for customer-facing forms and imports."""
import re

_EMAIL_RE = re.compile(r"^[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(\.[A-Za-z0-9-]+)*\.[A-Za-z]{2,}$")
_PHONE_RE = re.compile(r"^\+[1-9]\d{6,14}$")


def is_valid_email(address: str) -> bool:
    """Pragmatic check used at signup and checkout: one @, a dotted domain, no spaces.
    Does not try to implement RFC 5322."""
    address = address.strip()
    return len(address) <= 254 and bool(_EMAIL_RE.match(address)) and ".." not in address


def normalize_phone(raw: str) -> str:
    """E.164-ish: keep digits and a leading +. Raises ValueError if the result doesn't look valid."""
    digits = re.sub(r"[^\d+]", "", raw.strip())
    if digits.startswith("00"):
        digits = "+" + digits[2:]
    if not _PHONE_RE.match(digits):
        raise ValueError(f"invalid phone number: {raw!r}")
    return digits


def require(condition: bool, message: str) -> None:
    """Raise ValueError(message) unless condition holds. Used by importers and form handlers."""
    if not condition:
        raise ValueError(message)


def clamp(value: int, low: int, high: int) -> int:
    return max(low, min(high, value))
"""Customer registry used by checkout and the admin API."""
from shopkit.customers.models import Address, Customer
from shopkit.errors import Conflict, NotFound, ShopError
from shopkit.utils.ids import new_id
from shopkit.utils.validation import is_valid_email


class CustomerNotFound(NotFound):
    pass


class EmailTaken(Conflict):
    pass


class InvalidEmail(ShopError):
    http_status = 422


class CustomerDirectory:
    def __init__(self):
        self._by_id: dict[str, Customer] = {}

    def register(self, email: str, name: str, marketing_opt_in: bool = False) -> Customer:
        email = email.strip().lower()
        if not is_valid_email(email):
            raise InvalidEmail(f"invalid email {email!r}", email=email)
        if self.find_by_email(email):
            raise EmailTaken(f"{email} is already registered", email=email)
        customer = Customer(id=new_id("cus"), email=email, name=name.strip(),
                            marketing_opt_in=marketing_opt_in)
        self._by_id[customer.id] = customer
        return customer

    def get(self, customer_id: str) -> Customer:
        try:
            return self._by_id[customer_id]
        except KeyError:
            raise CustomerNotFound(f"no customer {customer_id}", customer_id=customer_id) from None

    def find_by_email(self, email: str) -> Customer | None:
        email = email.strip().lower()
        return next((c for c in self._by_id.values() if c.email == email), None)

    def add_address(self, customer_id: str, address: Address, default: bool = False) -> None:
        customer = self.get(customer_id)
        if default:
            customer.addresses.insert(0, address)
        else:
            customer.addresses.append(address)

    def opted_in(self) -> list[Customer]:
        return [c for c in self._by_id.values() if c.marketing_opt_in]
"""Outgoing email. Messages are queued; a worker hands them to the mail provider."""
from dataclasses import dataclass

from shopkit.config import SETTINGS
from shopkit.notifications.templates import TEMPLATES, render_template
from shopkit.utils.validation import is_valid_email


@dataclass(frozen=True)
class Email:
    to: str
    subject: str
    body: str
    reply_to: str = SETTINGS.support_email


class Outbox:
    def __init__(self):
        self.queued: list[Email] = []

    def send(self, to: str, template: str, **values) -> Email:
        if not is_valid_email(to):
            raise ValueError(f"invalid recipient {to!r}")
        subject_t, body_t = TEMPLATES[template]
        email = Email(to, render_template(subject_t, values), render_template(body_t, values))
        self.queued.append(email)
        return email

    def drain(self) -> list[Email]:
        out, self.queued = self.queued, []
        return out
